static int sumEven(int max) {
    int sum = 0;
    for (int i = 1; i <= max; i++) if (i % 2 == 0) sum += i;
    return sum;
}

while.declarations:
static int digits(int n) {
    if (n < 0) throw new IllegalArgumentException("Nichtnegativ erwartet");
    int count = 1;
    while (n >= 10) { n /= 10; count++; }
    return count;
}

array-length.declarations:
static double average(int[] values) {
    if (values.length == 0) throw new IllegalArgumentException("Array leer");
    long sum = 0;
    for (int n : values) sum += n;
    return (double)sum / values.length;
}

