string-find.declarations:
static int count(String text, String needle) {
    if (needle.isEmpty()) throw new IllegalArgumentException("Suchtext leer");
    int count = 0, start = 0, index;
    while ((index = text.indexOf(needle, start)) >= 0) { count++; start = index + needle.length(); }
    return count;
}

