test-boundary.code:
int[] input = {-1, 42, 101}, expected = {0, 42, 100};
for (int i = 0; i < input.length; i++) {
    int actual = Math.max(0, Math.min(100, input[i]));
    if (actual != expected[i]) throw new AssertionError("Fall " + i);
}
System.out.println("3 Grenztests bestanden");

